package com.agepony.core.recipients

import com.agepony.core.Age
import com.agepony.core.Stanza
import org.junit.jupiter.api.Assertions.assertArrayEquals
import org.junit.jupiter.api.Assertions.assertEquals
import org.junit.jupiter.api.Assertions.assertNotNull
import org.junit.jupiter.api.Assertions.assertNull
import org.junit.jupiter.api.Assertions.assertTrue
import org.junit.jupiter.api.Test
import java.util.HexFormat

/**
 * Known-answer tests for the MLKEM768-X25519 hybrid recipient (age1pq / mlkem768x25519).
 *
 * The vectors below were generated by the filippo.io/hpke reference implementation —
 * the exact construction the `age` CLI v1.3.0+ uses — with a fixed identity seed,
 * fixed encapsulation randomness, and a fixed file key. Passing these proves byte-for-byte
 * interoperability with standard age post-quantum recipients. See the update log for provenance.
 */
class HybridRecipientTests {
    private val hex = HexFormat.of()

    // Identity seed (AGE-SECRET-KEY-PQ- payload).
    private val seed = hex.parseHex(
        "000102030405060708090a0b0c0d0e0f101112131415161718191a1b1c1d1e1f"
    )

    // Expected 1216-byte hybrid public key derived from `seed`.
    private val expectedPublicKey = hex.parseHex(
        ""
    )

    // File key (16 bytes) and the 64-byte deterministic encapsulation randomness.
    private val fileKey = hex.parseHex("404142434445464748494a4b4c4d4e4f")
    private val testRandom = hex.parseHex(
        "808182838485868788898a8b8c8d8e8f909192939495969798999a9b9c9d9e9fa0a1a2a3a4a5a6a7a8a9aaabacadaeafb0b1b2b3b4b5b6b7b8b9babbbcbdbebf"
    )

    // Expected 1120-byte encapsulation and 32-byte sealed body.
    private val expectedEnc = hex.parseHex(
        ""
    )
    private val expectedBody = hex.parseHex(
        "2998be049fb54ca8f7830eb73b557844730bf0229d48159ac2d95e51eb02d8f3"
    )

    @Test
    fun publicKeyDerivedFromSeedMatchesReference() {
        assertArrayEquals(expectedPublicKey, HybridIdentity(seed).publicKey)
    }

    @Test
    fun deterministicWrapMatchesReferenceVector() {
        val stanza = HybridRecipient(expectedPublicKey).wrap(fileKey, testRandom)
        assertEquals("mlkem768x25519", stanza.type)
        assertEquals(1, stanza.args.size)
        assertArrayEquals(expectedEnc, Stanza.base64Decode(stanza.args[0]))
        assertArrayEquals(expectedBody, stanza.body)
    }

    @Test
    fun identityUnwrapsReferenceStanza() {
        val stanza = Stanza("mlkem768x25519", listOf(Stanza.base64NoPad(expectedEnc)), expectedBody)
        val recovered = HybridIdentity(seed).unwrap(stanza)
        assertNotNull(recovered)
        assertArrayEquals(fileKey, recovered)
    }

    @Test
    fun wrapThenUnwrapRoundTrips() {
        val id = HybridIdentity.generate()
        val fk = ByteArray(16) { it.toByte() }
        val stanza = id.recipient().wrap(fk)
        assertArrayEquals(fk, id.unwrap(stanza))
    }

    @Test
    fun endToEndThroughAgePipeline() {
        val id = HybridIdentity.generate()
        val plaintext = "hello post-quantum age\n".toByteArray()
        val ciphertext = Age.encrypt(plaintext, listOf(id.recipient()))
        assertArrayEquals(plaintext, Age.decrypt(ciphertext, listOf(id)))
    }

    @Test
    fun bech32RoundTripsRecipientAndIdentity() {
        val id = HybridIdentity(seed)
        val recipientStr = id.recipient().toBech32()
        val identityStr = id.toBech32()
        assertTrue(recipientStr.startsWith("age1pq1"))
        assertTrue(identityStr.startsWith("AGE-SECRET-KEY-PQ-1"))
        assertArrayEquals(id.publicKey, HybridRecipient(recipientStr).publicKey)
        assertArrayEquals(id.seed, HybridIdentity(identityStr).seed)
    }

    @Test
    fun unwrapReturnsNullForForeignStanza() {
        val stanza = Stanza("X25519", listOf(Stanza.base64NoPad(ByteArray(32))), ByteArray(32))
        assertNull(HybridIdentity(seed).unwrap(stanza))
    }
}
